-- LOCAL CANDIDATE ONLY. Requires the shared clinical RLS helpers from
-- 20261107020000 plus portal-link candidates through 20261124000000.
-- Never apply remotely without review.
CREATE TABLE public.workout_plans (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  patient_id bigint NOT NULL,
  workspace_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT workout_plans_patient_workspace_fkey FOREIGN KEY (workspace_id, patient_id)
    REFERENCES public.patients(workspace_id, id) MATCH SIMPLE ON DELETE NO ACTION NOT VALID,
  CONSTRAINT workout_plans_workspace_id_id_key UNIQUE (workspace_id, id)
);
CREATE TABLE public.workout_plan_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workout_plan_id bigint NOT NULL,
  workspace_id uuid,
  title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 160),
  goal text NOT NULL DEFAULT '', frequency text NOT NULL DEFAULT '',
  valid_from date, valid_until date, general_notes text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')),
  version integer NOT NULL CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz,
  FOREIGN KEY (workspace_id, workout_plan_id) REFERENCES public.workout_plans(workspace_id,id) ON DELETE NO ACTION NOT VALID,
  UNIQUE (workspace_id, id), UNIQUE (workout_plan_id, version)
);
CREATE TABLE public.workout_sessions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  version_id bigint NOT NULL, workspace_id uuid,
  title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 120),
  notes text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0,
  FOREIGN KEY (workspace_id, version_id) REFERENCES public.workout_plan_versions(workspace_id,id) ON DELETE CASCADE NOT VALID,
  UNIQUE (workspace_id,id), UNIQUE (version_id,id)
);
CREATE TABLE public.workout_plan_exercises (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id bigint NOT NULL, workspace_id uuid,
  name text NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 160),
  sets text NOT NULL DEFAULT '', repetitions text NOT NULL DEFAULT '', reference_load text NOT NULL DEFAULT '',
  rest text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', demo_url text NOT NULL DEFAULT '',
  sort_order integer NOT NULL DEFAULT 0,
  FOREIGN KEY (workspace_id, session_id) REFERENCES public.workout_sessions(workspace_id,id) ON DELETE CASCADE NOT VALID,
  UNIQUE (workspace_id,id)
);
CREATE TABLE public.workout_session_logs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  version_id bigint NOT NULL, workout_session_id bigint NOT NULL, patient_id bigint NOT NULL, workspace_id uuid,
  auth_user_id uuid NOT NULL DEFAULT auth.uid(), performed_at timestamptz NOT NULL DEFAULT now(),
  perceived_difficulty smallint CHECK (perceived_difficulty BETWEEN 1 AND 10), notes text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (workspace_id,version_id) REFERENCES public.workout_plan_versions(workspace_id,id) ON DELETE NO ACTION NOT VALID,
  FOREIGN KEY (version_id,workout_session_id) REFERENCES public.workout_sessions(version_id,id) ON DELETE NO ACTION NOT VALID,
  FOREIGN KEY (workspace_id,workout_session_id) REFERENCES public.workout_sessions(workspace_id,id) ON DELETE NO ACTION NOT VALID,
  FOREIGN KEY (workspace_id,patient_id) REFERENCES public.patients(workspace_id,id) MATCH SIMPLE ON DELETE NO ACTION NOT VALID
);
CREATE TABLE public.workout_exercise_logs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_log_id bigint NOT NULL REFERENCES public.workout_session_logs(id) ON DELETE CASCADE,
  exercise_id bigint NOT NULL REFERENCES public.workout_plan_exercises(id) ON DELETE NO ACTION,
  exercise_name text NOT NULL, load_used text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT ''
);
CREATE INDEX workout_plans_patient_idx ON public.workout_plans(workspace_id,patient_id);
CREATE INDEX workout_versions_plan_idx ON public.workout_plan_versions(workout_plan_id,version DESC);
CREATE INDEX workout_sessions_version_idx ON public.workout_sessions(version_id,sort_order);
CREATE INDEX workout_exercises_session_idx ON public.workout_plan_exercises(session_id,sort_order);
CREATE INDEX workout_session_logs_patient_idx ON public.workout_session_logs(workspace_id,patient_id,performed_at DESC);

CREATE FUNCTION public.derive_workout_workspace() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE v_workspace uuid;
BEGIN
 IF TG_TABLE_NAME='workout_plans' THEN
   SELECT workspace_id INTO v_workspace FROM public.patients WHERE id=NEW.patient_id;
 ELSIF TG_TABLE_NAME='workout_plan_versions' THEN
   SELECT workspace_id INTO v_workspace FROM public.workout_plans WHERE id=NEW.workout_plan_id;
 ELSIF TG_TABLE_NAME='workout_sessions' THEN
   SELECT workspace_id INTO v_workspace FROM public.workout_plan_versions WHERE id=NEW.version_id;
 ELSIF TG_TABLE_NAME='workout_plan_exercises' THEN
   SELECT workspace_id INTO v_workspace FROM public.workout_sessions WHERE id=NEW.session_id;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'workout parent not found'; END IF;
 IF TG_OP='UPDATE' AND NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN RAISE EXCEPTION 'workout workspace is immutable'; END IF;
 NEW.workspace_id := v_workspace;
 RETURN NEW;
END; $$;
CREATE TRIGGER workout_plans_workspace BEFORE INSERT OR UPDATE ON public.workout_plans FOR EACH ROW EXECUTE FUNCTION public.derive_workout_workspace();
CREATE TRIGGER workout_versions_workspace BEFORE INSERT OR UPDATE ON public.workout_plan_versions FOR EACH ROW EXECUTE FUNCTION public.derive_workout_workspace();
CREATE TRIGGER workout_sessions_workspace BEFORE INSERT OR UPDATE ON public.workout_sessions FOR EACH ROW EXECUTE FUNCTION public.derive_workout_workspace();
CREATE TRIGGER workout_exercises_workspace BEFORE INSERT OR UPDATE ON public.workout_plan_exercises FOR EACH ROW EXECUTE FUNCTION public.derive_workout_workspace();

ALTER TABLE public.workout_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.workout_plan_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.workout_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.workout_plan_exercises ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.workout_session_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.workout_exercise_logs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.workout_plans,public.workout_plan_versions,public.workout_sessions,public.workout_plan_exercises,public.workout_session_logs,public.workout_exercise_logs FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workout_plans,public.workout_plan_versions,public.workout_sessions,public.workout_plan_exercises TO authenticated;
GRANT SELECT,INSERT ON public.workout_session_logs,public.workout_exercise_logs TO authenticated;
GRANT USAGE,SELECT ON SEQUENCE public.workout_plans_id_seq,public.workout_plan_versions_id_seq,public.workout_sessions_id_seq,public.workout_plan_exercises_id_seq,public.workout_session_logs_id_seq,public.workout_exercise_logs_id_seq TO authenticated;

CREATE POLICY workout_plans_admin ON public.workout_plans FOR ALL TO authenticated USING(public.can_manage_clinical_patient_scope(patient_id,workspace_id)) WITH CHECK(public.can_manage_clinical_patient_scope(patient_id,workspace_id));
CREATE POLICY workout_plans_patient_read ON public.workout_plans FOR SELECT TO authenticated USING ((workspace_id IS NULL AND public.can_read_legacy_clinical_patient(patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links l WHERE l.auth_user_id=(SELECT auth.uid()) AND l.workspace_id=workout_plans.workspace_id AND l.patient_id=workout_plans.patient_id AND l.status='active'));
CREATE POLICY workout_versions_admin ON public.workout_plan_versions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.workout_plans p WHERE p.id=workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM workout_plan_versions.workspace_id AND public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.workout_plans p WHERE p.id=workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM workout_plan_versions.workspace_id AND public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id)));
CREATE POLICY workout_versions_patient_read ON public.workout_plan_versions FOR SELECT TO authenticated USING(status='published' AND EXISTS(SELECT 1 FROM public.workout_plans p WHERE p.id=workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM workout_plan_versions.workspace_id AND ((p.workspace_id IS NULL AND public.can_read_legacy_clinical_patient(p.patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links l WHERE l.auth_user_id=(SELECT auth.uid()) AND l.workspace_id=p.workspace_id AND l.patient_id=p.patient_id AND l.status='active'))));
CREATE POLICY workout_sessions_admin ON public.workout_sessions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.workout_plan_versions v JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE v.id=version_id AND v.workspace_id IS NOT DISTINCT FROM workout_sessions.workspace_id AND public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.workout_plan_versions v JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE v.id=version_id AND v.workspace_id IS NOT DISTINCT FROM workout_sessions.workspace_id AND public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id)));
CREATE POLICY workout_sessions_patient_read ON public.workout_sessions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.workout_plan_versions v JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE v.id=version_id AND v.workspace_id IS NOT DISTINCT FROM workout_sessions.workspace_id AND v.status='published' AND ((p.workspace_id IS NULL AND public.can_read_legacy_clinical_patient(p.patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links l WHERE l.auth_user_id=(SELECT auth.uid()) AND l.workspace_id=p.workspace_id AND l.patient_id=p.patient_id AND l.status='active'))));
CREATE POLICY workout_exercises_admin ON public.workout_plan_exercises FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.workout_sessions s JOIN public.workout_plan_versions v ON v.id=s.version_id AND v.workspace_id IS NOT DISTINCT FROM s.workspace_id JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE s.id=session_id AND s.workspace_id IS NOT DISTINCT FROM workout_plan_exercises.workspace_id AND public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.workout_sessions s JOIN public.workout_plan_versions v ON v.id=s.version_id AND v.workspace_id IS NOT DISTINCT FROM s.workspace_id JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE s.id=session_id AND s.workspace_id IS NOT DISTINCT FROM workout_plan_exercises.workspace_id AND public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id)));
CREATE POLICY workout_exercises_patient_read ON public.workout_plan_exercises FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.workout_sessions s JOIN public.workout_plan_versions v ON v.id=s.version_id AND v.workspace_id IS NOT DISTINCT FROM s.workspace_id JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE s.id=session_id AND s.workspace_id IS NOT DISTINCT FROM workout_plan_exercises.workspace_id AND v.status='published' AND ((p.workspace_id IS NULL AND public.can_read_legacy_clinical_patient(p.patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links l WHERE l.auth_user_id=(SELECT auth.uid()) AND l.workspace_id=p.workspace_id AND l.patient_id=p.patient_id AND l.status='active'))));
CREATE POLICY workout_logs_admin ON public.workout_session_logs FOR ALL TO authenticated USING(public.can_manage_clinical_patient_scope(patient_id,workspace_id)) WITH CHECK(public.can_manage_clinical_patient_scope(patient_id,workspace_id));
CREATE POLICY workout_logs_patient_read ON public.workout_session_logs FOR SELECT TO authenticated USING((workspace_id IS NULL AND public.can_read_legacy_clinical_patient(patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links l WHERE l.auth_user_id=(SELECT auth.uid()) AND l.workspace_id=workout_session_logs.workspace_id AND l.patient_id=workout_session_logs.patient_id AND l.status='active'));
CREATE POLICY workout_logs_patient_insert ON public.workout_session_logs FOR INSERT TO authenticated WITH CHECK(auth_user_id=(SELECT auth.uid()) AND EXISTS(SELECT 1 FROM public.workout_plan_versions v JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id JOIN public.workout_sessions s ON s.version_id=v.id AND s.id=workout_session_logs.workout_session_id AND s.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE v.id=version_id AND v.status='published' AND p.patient_id=workout_session_logs.patient_id AND p.workspace_id IS NOT DISTINCT FROM workout_session_logs.workspace_id AND ((p.workspace_id IS NULL AND public.can_read_legacy_clinical_patient(p.patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links l WHERE l.auth_user_id=(SELECT auth.uid()) AND l.workspace_id=p.workspace_id AND l.patient_id=p.patient_id AND l.status='active'))));
CREATE POLICY workout_exercise_logs_read ON public.workout_exercise_logs FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.workout_session_logs l JOIN public.workout_plan_versions v ON v.id=l.version_id AND v.workspace_id IS NOT DISTINCT FROM l.workspace_id JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id WHERE l.id=session_log_id AND l.patient_id=p.patient_id AND l.workspace_id IS NOT DISTINCT FROM p.workspace_id AND (public.can_manage_clinical_patient_scope(p.patient_id,p.workspace_id) OR (l.workspace_id IS NULL AND public.can_read_legacy_clinical_patient(l.patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links x WHERE x.auth_user_id=(SELECT auth.uid()) AND x.workspace_id=l.workspace_id AND x.patient_id=l.patient_id AND x.status='active'))));
CREATE POLICY workout_exercise_logs_insert ON public.workout_exercise_logs FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.workout_session_logs l JOIN public.workout_plan_exercises e ON e.id=exercise_id JOIN public.workout_sessions s ON s.id=e.session_id AND s.workspace_id IS NOT DISTINCT FROM e.workspace_id JOIN public.workout_plan_versions v ON v.id=s.version_id AND v.workspace_id IS NOT DISTINCT FROM s.workspace_id WHERE l.id=session_log_id AND l.workout_session_id=s.id AND v.id=l.version_id AND e.name=exercise_name AND (public.can_manage_clinical_patient_scope(l.patient_id,l.workspace_id) OR (l.auth_user_id=(SELECT auth.uid()) AND ((l.workspace_id IS NULL AND public.can_read_legacy_clinical_patient(l.patient_id)) OR EXISTS(SELECT 1 FROM public.patient_portal_workspace_links x WHERE x.auth_user_id=(SELECT auth.uid()) AND x.workspace_id=l.workspace_id AND x.patient_id=l.patient_id AND x.status='active')))));

CREATE FUNCTION public.validate_workout_session_log_scope() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE v_expected_patient bigint; v_expected_workspace uuid;
BEGIN
  SELECT p.patient_id,p.workspace_id INTO v_expected_patient,v_expected_workspace
  FROM public.workout_sessions s
  JOIN public.workout_plan_versions v ON v.id=s.version_id AND v.workspace_id IS NOT DISTINCT FROM s.workspace_id
  JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id
  WHERE s.id=NEW.workout_session_id AND v.id=NEW.version_id;
  IF NOT FOUND OR NEW.patient_id IS DISTINCT FROM v_expected_patient
     OR NEW.workspace_id IS DISTINCT FROM v_expected_workspace THEN
    RAISE EXCEPTION 'workout session log scope does not match its session and version';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER workout_session_logs_scope_check BEFORE INSERT ON public.workout_session_logs
  FOR EACH ROW EXECUTE FUNCTION public.validate_workout_session_log_scope();

CREATE FUNCTION public.create_workout_session_log(
  p_workout_session_id bigint, p_performed_at timestamptz, p_difficulty smallint,
  p_notes text, p_exercises jsonb
) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path TO '' AS $$
DECLARE v_log_id bigint; v_session record; v_item jsonb;
BEGIN
  SELECT s.id AS session_id, s.workspace_id, v.id AS version_id, v.status, p.patient_id
    INTO v_session FROM public.workout_sessions s
    JOIN public.workout_plan_versions v ON v.id=s.version_id AND v.workspace_id IS NOT DISTINCT FROM s.workspace_id
    JOIN public.workout_plans p ON p.id=v.workout_plan_id AND p.workspace_id IS NOT DISTINCT FROM v.workspace_id
    WHERE s.id=p_workout_session_id;
  IF NOT FOUND OR v_session.status <> 'published' THEN RAISE EXCEPTION 'published workout session not found'; END IF;
  INSERT INTO public.workout_session_logs(version_id,workout_session_id,patient_id,workspace_id,auth_user_id,performed_at,perceived_difficulty,notes)
    VALUES(v_session.version_id,v_session.session_id,v_session.patient_id,v_session.workspace_id,auth.uid(),COALESCE(p_performed_at,now()),p_difficulty,COALESCE(p_notes,''))
    RETURNING id INTO v_log_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_exercises,'[]'::jsonb)) LOOP
    INSERT INTO public.workout_exercise_logs(session_log_id,exercise_id,exercise_name,load_used,notes)
      SELECT v_log_id,e.id,e.name,COALESCE(v_item->>'load_used',''),COALESCE(v_item->>'notes','')
      FROM public.workout_plan_exercises e JOIN public.workout_sessions s ON s.id=e.session_id AND s.workspace_id IS NOT DISTINCT FROM e.workspace_id
      WHERE e.id=(v_item->>'exercise_id')::bigint AND s.id=v_session.session_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'exercise does not belong to workout session'; END IF;
  END LOOP;
  RETURN v_log_id;
END; $$;
REVOKE ALL ON FUNCTION public.create_workout_session_log(bigint,timestamptz,smallint,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_workout_session_log(bigint,timestamptz,smallint,text,jsonb) TO authenticated;

CREATE FUNCTION public.prevent_published_workout_version_changes() RETURNS trigger LANGUAGE plpgsql SET search_path TO '' AS $$
BEGIN
 IF TG_TABLE_NAME='workout_plan_versions' AND OLD.status IN ('published','archived') AND NOT (OLD.status='published' AND NEW.status='archived' AND (to_jsonb(NEW)-'status')=(to_jsonb(OLD)-'status')) THEN RAISE EXCEPTION 'published workout versions are immutable'; END IF;
 IF TG_TABLE_NAME='workout_sessions' AND EXISTS(SELECT 1 FROM public.workout_plan_versions v WHERE v.id=COALESCE(NEW.version_id,OLD.version_id) AND v.status IN ('published','archived')) THEN RAISE EXCEPTION 'published workout versions are immutable'; END IF;
 IF TG_TABLE_NAME='workout_plan_exercises' AND EXISTS(SELECT 1 FROM public.workout_sessions s JOIN public.workout_plan_versions v ON v.id=s.version_id WHERE s.id=COALESCE(NEW.session_id,OLD.session_id) AND v.status IN ('published','archived')) THEN RAISE EXCEPTION 'published workout versions are immutable'; END IF;
 RETURN COALESCE(NEW,OLD);
END; $$;
CREATE TRIGGER workout_versions_immutable BEFORE UPDATE OR DELETE ON public.workout_plan_versions FOR EACH ROW EXECUTE FUNCTION public.prevent_published_workout_version_changes();
CREATE TRIGGER workout_sessions_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.workout_sessions FOR EACH ROW EXECUTE FUNCTION public.prevent_published_workout_version_changes();
CREATE TRIGGER workout_exercises_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.workout_plan_exercises FOR EACH ROW EXECUTE FUNCTION public.prevent_published_workout_version_changes();
